<script setup lang="ts">import{shallowRef,onMounted,onUnmounted}from"vue";import Breadcrumbs from"./Breadcrumbs.vue";import ModelPrivacyStatus from"../system/ModelPrivacyStatus.vue";const emit=defineEmits<{openSearch:[];openMenu:[]}>();const onKey=(event:KeyboardEvent)=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="k"){event.preventDefault();emit("openSearch")}};onMounted(()=>window.addEventListener("keydown",onKey));onUnmounted(()=>window.removeEventListener("keydown",onKey));const menuOpen=shallowRef(false);</script><template><header class="topbar"><button class="mobile-menu" aria-label="打开导航" @click="emit('openMenu')">☰</button><Breadcrumbs/><div class="tools"><button class="search" @click="emit('openSearch')">⌕ 全局搜索 <kbd>Ctrl K</kbd></button><button class="quick" @click="menuOpen=!menuOpen">＋ 新建</button><div v-if="menuOpen" class="quick-menu"><RouterLink to="/literature-search">发起文献检索</RouterLink><RouterLink to="/sources">添加知识源</RouterLink></div><ModelPrivacyStatus/></div></header></template><style scoped>.topbar{position:sticky;top:0;z-index:10;display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1rem 1.4rem;border-bottom:1px solid var(--line);background:rgba(255,255,255,.9);backdrop-filter:blur(12px)}.tools{display:flex;align-items:center;gap:.7rem;position:relative}.search,.quick,.mobile-menu{border:1px solid var(--line);border-radius:7px;padding:.45rem .65rem;background:#fff;color:var(--navy-800)}.quick{border-color:var(--blue-600);background:var(--blue-600);color:#fff}.quick-menu{position:absolute;right:4.4rem;top:2.5rem;display:grid;gap:.4rem;padding:.65rem;background:#fff;border:1px solid var(--line);border-radius:8px;box-shadow:var(--shadow);white-space:nowrap}.quick-menu a{color:var(--ink);text-decoration:none}.mobile-menu{display:none}@media(max-width:900px){.mobile-menu{display:block}.privacy{display:none}.search kbd{display:none}}</style>
